package com.vitahealth.tata.identitysubscription.domain.model.valueobjects;

/** A transient six-digit verification secret, never stored as plaintext account state. */
public record VerificationCode(String value) {
  /** Requires the ASCII code format generated by the verification workflow. */
  public VerificationCode {
    if (value == null || !value.matches("[0-9]{6}")) {
      throw new IllegalArgumentException("A six-digit verification code is required");
    }
  }

  /** Prevents the transient secret from appearing in diagnostic messages. */
  @Override
  public String toString() {
    return "VerificationCode[redacted]";
  }
}
